import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {CodingToolUpdateResult} from '../types'

export async function updateCodingTool(
  updatePath: string,
  tool: string,
  enabled: boolean,
): Promise<CodingToolUpdateResult> {
  try {
    const response = await verifiedFetchJSON(updatePath, {
      method: 'PUT',
      body: {tool, enabled},
    })

    if (!response.ok) {
      return {success: false, tool, enabled}
    }

    let payload: Partial<CodingToolUpdateResult> | null = null
    try {
      payload = (await response.json()) as Partial<CodingToolUpdateResult>
    } catch {
      payload = null
    }

    return {
      success: payload?.success ?? true,
      tool: payload?.tool ?? tool,
      enabled: payload?.enabled ?? enabled,
    }
  } catch {
    return {success: false, tool, enabled}
  }
}
