import {ControlGroup} from '@github-ui/control-group'
import {useCallback, useMemo, useState} from 'react'
import {InlineMessage} from '@primer/react/experimental'
import {updateCodingTool} from './services/api'
import {getToolDescription, getToolDisplayName, getToolIcon, type CodingToolsSettingsProps} from './types'
import styles from './CodingToolsSettingsPage.module.css'

const UPDATE_ERROR_MESSAGE = 'Unable to save coding tool preference. Please try again.'

export function CodingToolsSettingsPage({tools, settings, updatePath}: CodingToolsSettingsProps) {
  const initialSettings = useMemo(() => {
    const normalizedSettings: Record<string, boolean> = {}

    for (const tool of tools) {
      normalizedSettings[tool] = Boolean(settings[tool])
    }

    return normalizedSettings
  }, [tools, settings])

  const [toolSettings, setToolSettings] = useState<Record<string, boolean>>(initialSettings)
  const [errorByTool, setErrorByTool] = useState<Record<string, string>>({})

  const handleToggle = useCallback(
    async (tool: string) => {
      const previousValue = Boolean(toolSettings[tool])
      const nextValue = !previousValue

      setToolSettings(prev => ({
        ...prev,
        [tool]: nextValue,
      }))
      setErrorByTool(prev => ({
        ...prev,
        [tool]: '',
      }))

      const result = await updateCodingTool(updatePath, tool, nextValue)

      if (!result.success) {
        setToolSettings(prev => ({
          ...prev,
          [tool]: previousValue,
        }))
        setErrorByTool(prev => ({
          ...prev,
          [tool]: UPDATE_ERROR_MESSAGE,
        }))
      }
    },
    [toolSettings, updatePath],
  )

  return (
    <ControlGroup>
      {tools.map(tool => {
        const nameId = `${tool}-toggle-name`
        const descriptionId = `${tool}-toggle-description`
        const errorId = `${tool}-toggle-error`
        const ToolIcon = getToolIcon(tool)

        return (
          <ControlGroup.Item key={tool}>
            <ControlGroup.Title>
              <span className="d-inline-flex flex-items-center">
                {ToolIcon && (
                  <ToolIcon data-testid={`${tool}-icon`} className={`${styles.toolIcon} mr-3 flex-shrink-0`} />
                )}
                <span className="d-flex flex-column">
                  <span id={nameId}>{getToolDisplayName(tool)}</span>
                  <span id={descriptionId} className="color-fg-muted text-small text-semibold">
                    {getToolDescription(tool)}
                  </span>
                </span>
              </span>
            </ControlGroup.Title>
            {errorByTool[tool] && (
              <ControlGroup.Description>
                <InlineMessage role="alert" id={errorId} size="small" variant="critical" className={styles.inlineError}>
                  {errorByTool[tool]}
                </InlineMessage>
              </ControlGroup.Description>
            )}
            <ControlGroup.ToggleSwitch
              aria-labelledby={nameId}
              aria-describedby={errorByTool[tool] ? `${descriptionId} ${errorId}` : descriptionId}
              checked={Boolean(toolSettings[tool])}
              onClick={() => {
                void handleToggle(tool)
              }}
            />
          </ControlGroup.Item>
        )
      })}
    </ControlGroup>
  )
}
